import{_ as t,C as n,c as a,o as i,a3 as e,G as r}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Register sessions","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/sessions/index.md","filePath":"master/sales/point-of-sale/sessions/index.md","lastUpdated":1793074831000}'),l={name:"master/sales/point-of-sale/sessions/index.md"};function h(d,s,c,g,p,u){const o=n("ImagePopup");return i(),a("div",null,[s[0]||(s[0]=e('<h1 id="register-sessions" tabindex="-1">Register sessions <a class="header-anchor" href="#register-sessions" aria-label="Permalink to &quot;Register sessions&quot;">​</a></h1><p>A session is one working period of a register, from the moment you open the cash drawer to the moment you count it and close. Every order, payment and cash movement belongs to a session. Sessions keep your daily cash and sales apart, so you can check each shift on its own.</p><blockquote><p><strong>In simple words:</strong> Open the register to start the day, sell, then close the session to count the cash and post the sales to accounting.</p></blockquote><p>A register can have only one live session at a time. The next session starts only after the last one is closed.</p><h2 id="the-session-life-cycle" tabindex="-1">The session life cycle <a class="header-anchor" href="#the-session-life-cycle" aria-label="Permalink to &quot;The session life cycle&quot;">​</a></h2><p>Each session moves through these statuses.</p><ul><li><strong>Opening Control:</strong> The session exists, but nobody has confirmed the opening cash yet. You confirm it in the <strong>Opening Control</strong> window.</li><li><strong>In Progress:</strong> The register is open. You can sell, take refunds and record cash in and out.</li><li><strong>Closing Control:</strong> The session has stopped selling and waits for the final cash count.</li><li><strong>Closed &amp; Posted:</strong> The cash is counted and the sales are posted to accounting. The session is final.</li></ul><p>The flow is: open the register, sell, record cash in and out, close the session, then review the numbers in reports.</p><h2 id="the-sessions-list" tabindex="-1">The Sessions list <a class="header-anchor" href="#the-sessions-list" aria-label="Permalink to &quot;The Sessions list&quot;">​</a></h2><p>Go to <code>Point of Sale → Orders → Sessions</code>. This list shows every session of every register.</p>',10)),r(o,{src:"/images1/pos/sessions_list.png",alt:"Sessions list with the Default, Open, Closing Control and Closed tabs and one row per session"}),s[1]||(s[1]=e('<h3 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h3><ul><li><strong>Default:</strong> All sessions.</li><li><strong>Open:</strong> Sessions that are in progress.</li><li><strong>Closing Control:</strong> Sessions waiting for the final count.</li><li><strong>Closed:</strong> Sessions that are finished and posted.</li></ul><h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><p>The list shows <strong>Session ID</strong>, <strong>Point of Sale</strong>, <strong>Opened By</strong>, <strong>Opening Date</strong>, <strong>Closing Date</strong>, <strong>Starting Balance</strong>, <strong>Ending Balance</strong>, <strong>Theoretical Closing Balance</strong> and <strong>Status</strong>. Some columns are hidden at first. Use the column toggle to show more.</p><p>A session ID looks like <code>TNE/SESSION/00002</code>. The first part is the <strong>Short Code</strong> of the register. See <a href="./../get-started/set-up-a-register.html">Set up a register</a>.</p><h3 id="row-actions" tabindex="-1">Row actions <a class="header-anchor" href="#row-actions" aria-label="Permalink to &quot;Row actions&quot;">​</a></h3><ul><li><strong>View:</strong> Opens the session with its orders and payments.</li><li><strong>Cash In/Out:</strong> Records money put into or taken out of the drawer. See <a href="./cash-in-and-out.html">Cash in and out</a>.</li><li><strong>Close Session:</strong> Counts the drawer and closes the session. See <a href="./close-session.html">Close a session</a>.</li><li><strong>Open Session:</strong> Shows only on a session in <strong>Opening Control</strong>. It confirms the opening cash and starts the session.</li></ul><p>Use <strong>Group by</strong> or the filters to find a session by register or status.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>TechNest Electronics opens its retail register with 1,750 in the drawer. The session is TNE/SESSION/00002. The team sells two orders, takes a refund and pays a courier 500 from the drawer. At closing they count 7,847, which matches the expected balance, so the session closes with no difference.</p><h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><ol><li><a href="./open-register.html">Open the register</a></li><li><a href="./cash-in-and-out.html">Cash in and out</a></li><li><a href="./close-session.html">Close a session</a></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Close the session every day. A session left open for many days is flagged on the <strong>Dashboard</strong> so you can find it.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../selling/">Selling at the terminal</a></li><li><a href="./../reporting/session-report.html">Session report</a></li><li><a href="./../payments-setup/payment-methods.html">Payment methods</a></li></ul>',15))])}const S=t(l,[["render",h]]);export{f as __pageData,S as default};
